<template>
	<view class="page">
		<!-- 顶部蓝色信息条 -->
		<view class="header-bar">
			<view class="header-left">
				<text class="header-title">{{ userRole === 'enterprise' ? '我的关联企业' : '我的负责企业' }}</text>
				<text class="header-role">当前身份：{{ userRole === 'enterprise' ? '企业用户' : '内部员工' }}</text>
			</view>
			<view class="header-count">
				<text class="count-num">{{ enterprises.length }}</text>
				<text class="count-unit">家</text>
			</view>
		</view>

		<!-- 板块标题 -->
		<view class="section-title">
			<text class="section-title-text">{{ userRole === 'enterprise' ? '关联企业列表' : '负责企业列表' }}</text>
			<text class="section-title-extra">实时同步</text>
		</view>

		<!-- 空态 -->
		<view class="empty-box" v-if="enterprises.length === 0">
			<uni-icons type="home" size="56" color="#c9d2e2"></uni-icons>
			<text class="empty-text" v-if="userRole === 'enterprise'">暂无关联企业，点击下方按钮添加</text>
			<text class="empty-text" v-else>暂无负责企业，请等待系统分配</text>
		</view>

		<!-- 企业卡片列表 -->
		<view class="enterprise-list" v-else>
			<view class="ent-card" v-for="(e, i) in enterprises" :key="e.id || i">
				<view class="ent-top">
					<view class="ent-icon-box" :class="{ internal: userRole !== 'enterprise' }">
						<uni-icons :type="userRole === 'enterprise' ? 'home-filled' : 'person-filled'" size="20" color="#ffffff"></uni-icons>
					</view>
					<view class="ent-info">
						<text class="ent-name">{{ e.name }}</text>
						<text class="ent-sub">我的身份：{{ e.role }}</text>
					</view>
					<view class="ent-status" :class="statusClass(e.status)">
						<text class="ent-status-text">{{ e.status }}</text>
					</view>
				</view>
				<view class="ent-actions">
					<!-- 企业用户：修改资料 / 转让 / 解除关联 -->
					<block v-if="userRole === 'enterprise'">
						<view class="ent-action-btn outline" @click="onEntAction('edit', e)">
							<uni-icons type="compose" size="14" color="#2979ff"></uni-icons>
							<text class="ent-action-text blue">修改资料</text>
						</view>
						<view class="ent-action-btn outline" @click="onEntAction('transfer', e)">
							<uni-icons type="redo" size="14" color="#f08c20"></uni-icons>
							<text class="ent-action-text orange">转让企业</text>
						</view>
						<view class="ent-action-btn outline danger" @click="onEntAction('remove', e)">
							<uni-icons type="trash" size="14" color="#FF6B6B"></uni-icons>
							<text class="ent-action-text red">解除关联</text>
						</view>
					</block>
					<!-- 内部员工：查看详情 / 联系法人 -->
					<block v-else>
						<view class="ent-action-btn outline" @click="onEntAction('view', e)">
							<uni-icons type="eye" size="14" color="#2979ff"></uni-icons>
							<text class="ent-action-text blue">查看详情</text>
						</view>
						<view class="ent-action-btn outline" @click="onEntAction('contact', e)">
							<uni-icons type="headphones" size="14" color="#2ea86b"></uni-icons>
							<text class="ent-action-text green">联系法人</text>
						</view>
					</block>
				</view>
			</view>
		</view>

		<!-- 企业用户：添加按钮 -->
		<view class="list-footer" v-if="userRole === 'enterprise'">
			<view class="add-ent-btn" @click="onEntAction('add')">
				<uni-icons type="plus" size="18" color="#2979ff"></uni-icons>
				<text class="add-ent-text">添加关联企业</text>
			</view>
		</view>

		<view class="bottom-space"></view>
	</view>
</template>

<script>
	const STORAGE_KEY = 'qcc_user_profile_data'

	// 默认数据（当 storage 未写入时兜底，避免无列表渲染）
	const roleDefaults = {
		enterprise: {
			enterprises: [
				{ id: 1, name: '上海明远科技有限公司', role: '法人', status: '正常' },
				{ id: 2, name: '上海启航贸易有限公司', role: '股东', status: '正常' },
				{ id: 3, name: '杭州远景咨询有限公司', role: '法人', status: '变更中' }
			]
		},
		internal: {
			enterprises: [
				{ id: 1, name: '上海明远科技有限公司', role: '对接经理', status: '跟进中' },
				{ id: 2, name: '上海启航贸易有限公司', role: '对接经理', status: '正常' },
				{ id: 3, name: '杭州远景咨询有限公司', role: '对接经理', status: '正常' },
				{ id: 4, name: '苏州恒源实业有限公司', role: '协助', status: '正常' },
				{ id: 5, name: '南京宏图网络有限公司', role: '协助', status: '待联系' }
			]
		}
	}

	export default {
		data() {
			return {
				userRole: 'enterprise',
				enterprises: []
			}
		},
		onLoad() {
			this.loadFromStorage()
		},
		onShow() {
			// 每次显示都重读，保证与 profile / mine 页面改动同步
			this.loadFromStorage()
		},
		methods: {
			loadFromStorage() {
				const savedRole = uni.getStorageSync('qcc_user_role') || 'enterprise'
				this.userRole = savedRole
				const saved = uni.getStorageSync(STORAGE_KEY + '_' + savedRole)
				if (saved && saved.enterprises && Array.isArray(saved.enterprises)) {
					this.enterprises = JSON.parse(JSON.stringify(saved.enterprises))
				} else {
					const base = roleDefaults[savedRole] || roleDefaults.enterprise
					this.enterprises = JSON.parse(JSON.stringify(base.enterprises || []))
				}
			},

			statusClass(status) {
				if (status === '正常') return 'ok'
				if (status === '跟进中' || status === '变更中' || status === '审核中') return 'warn'
				return 'muted'
			},

			// 写入 storage：保留原表单字段，仅覆盖 enterprises
			persist() {
				const key = STORAGE_KEY + '_' + this.userRole
				const cur = uni.getStorageSync(key) || {}
				const next = Object.assign({}, cur, {
					enterprises: JSON.parse(JSON.stringify(this.enterprises))
				})
				uni.setStorageSync(key, next)
				// 同步 mine 页企业计数（mine 页 onShow 会重算，这里也单独写一下角色专用计数，方便 menu 直接读取）
				uni.setStorageSync('qcc_user_ent_count_' + this.userRole, this.enterprises.length)
			},

			onEntAction(action, ent) {
				switch (action) {
					case 'add':
						uni.showModal({
							title: '添加关联企业',
							editable: true,
							placeholderText: '请输入企业名称',
							confirmText: '添加',
							confirmColor: '#2979ff',
							success: (r) => {
								if (r.confirm && r.content && r.content.trim()) {
									this.enterprises.push({
										id: Date.now(),
										name: r.content.trim(),
										role: '法人',
										status: '审核中'
									})
									this.persist()
									uni.showToast({ title: '添加成功，等待审核', icon: 'success' })
								}
							}
						})
						break
					case 'edit':
						uni.showModal({
							title: '修改企业资料',
							content: `当前企业：${ent.name}\n请在下方输入新的企业名称（演示版）`,
							editable: true,
							placeholderText: '新的企业名称',
							confirmText: '保存',
							confirmColor: '#2979ff',
							success: (r) => {
								if (r.confirm && r.content && r.content.trim()) {
									ent.name = r.content.trim()
									this.persist()
									uni.showToast({ title: '已修改', icon: 'success' })
								}
							}
						})
						break
					case 'transfer':
						uni.showModal({
							title: '转让企业',
							content: `将「${ent.name}」法人身份转让给其他股东？转让后将失去法人权限。`,
							confirmText: '确认转让',
							confirmColor: '#f08c20',
							success: (r) => {
								if (r.confirm) {
									ent.role = '股东'
									this.persist()
									uni.showToast({ title: '转让成功', icon: 'success' })
								}
							}
						})
						break
					case 'remove':
						uni.showModal({
							title: '解除关联',
							content: `确认解除与「${ent.name}」的关联？`,
							confirmText: '确认解除',
							confirmColor: '#FF6B6B',
							success: (r) => {
								if (r.confirm) {
									const idx = this.enterprises.indexOf(ent)
									if (idx > -1) this.enterprises.splice(idx, 1)
									this.persist()
									uni.showToast({ title: '已解除关联', icon: 'success' })
								}
							}
						})
						break
					case 'view':
						uni.showModal({
							title: '企业详情',
							content: `企业：${ent.name}\n我的身份：${ent.role}\n状态：${ent.status}\n\n（演示占位：完整企业详情页后续接入）`,
							showCancel: false,
							confirmColor: '#2979ff'
						})
						break
					case 'contact':
						uni.showModal({
							title: '联系法人',
							content: `企业：${ent.name}\n联系电话：400-888-8888（转接）`,
							confirmText: '拨打',
							confirmColor: '#2ea86b',
							success: (r) => {
								if (r.confirm) uni.showToast({ title: '拨打中...', icon: 'none' })
							}
						})
						break
				}
			}
		}
	}
</script>

